-- LemmaYard problem catalog for Supabase, part 2 of 6 (SQL Editor -> New query -> paste -> Run).
-- Generated by `pnpm problems:export-sql` from problems/*; do not edit by hand.
-- The same catalog in one file is docs/supabase/problems.sql; the parts exist for SQL
-- editors that refuse a large paste. Run all 6 parts, in any order, after
-- docs/supabase/schema.sql (or `pnpm db:migrate`). Each part is its own transaction
-- over 14 problems, 13 tags and 1750 test cases (catalog: 50 problems,
-- 6625 test cases). It writes the same rows as `pnpm problems:import`: upsert by
-- slug (published), tags, and a full replacement of each problem's tags and test cases.
-- Safe to run again; it never unpublishes problems that are not listed here.
-- NOTE: this file contains the HIDDEN test cases too (is_sample = false). They are
-- public anyway, because problems/*/tests.json is committed to this repository.

BEGIN;

-- Refuse to run if another problem in the database already uses one of these numbers.
DO $$
DECLARE taken text;
BEGIN
  SELECT string_agg("slug" || ' (' || "number" || ')', ', ') INTO taken
  FROM "problems"
  WHERE "number" IN (32, 49, 10, 14, 3, 29, 38, 19, 33, 23, 8, 39, 45, 13)
    AND "slug" NOT IN ($ly$busiest-moment$ly$, $ly$checkpoint-tour$ly$, $ly$climbing-stairs$ly$, $ly$coin-change$ly$, $ly$contains-duplicate$ly$, $ly$deepest-bracket-nesting$ly$, $ly$earliest-free-server$ly$, $ly$edit-distance$ly$, $ly$even-bit-xor-pairs$ly$, $ly$first-overdraft-day$ly$, $ly$fizz-buzz$ly$, $ly$growing-clubs$ly$, $ly$guarded-queens$ly$, $ly$house-robber$ly$);
  IF taken IS NOT NULL THEN
    RAISE EXCEPTION 'problem numbers already used by other problems in the database: %', taken;
  END IF;
END $$;

-- Park the numbers of existing rows so renumbering between them cannot collide;
-- every parked row gets its real number back from the upserts below.
UPDATE "problems" SET "number" = "number" + 1000000000
WHERE "slug" IN ($ly$busiest-moment$ly$, $ly$checkpoint-tour$ly$, $ly$climbing-stairs$ly$, $ly$coin-change$ly$, $ly$contains-duplicate$ly$, $ly$deepest-bracket-nesting$ly$, $ly$earliest-free-server$ly$, $ly$edit-distance$ly$, $ly$even-bit-xor-pairs$ly$, $ly$first-overdraft-day$ly$, $ly$fizz-buzz$ly$, $ly$growing-clubs$ly$, $ly$guarded-queens$ly$, $ly$house-robber$ly$);

INSERT INTO "tags" ("slug", "name") VALUES
  ($ly$array$ly$, $ly$Array$ly$),
  ($ly$sorting$ly$, $ly$Sorting$ly$),
  ($ly$prefix-sum$ly$, $ly$Prefix Sum$ly$),
  ($ly$bit-manipulation$ly$, $ly$Bit Manipulation$ly$),
  ($ly$dynamic-programming$ly$, $ly$Dynamic Programming$ly$),
  ($ly$math$ly$, $ly$Math$ly$),
  ($ly$hash-table$ly$, $ly$Hash Table$ly$),
  ($ly$string$ly$, $ly$String$ly$),
  ($ly$stack$ly$, $ly$Stack$ly$),
  ($ly$heap$ly$, $ly$Heap$ly$),
  ($ly$union-find$ly$, $ly$Union Find$ly$),
  ($ly$graph$ly$, $ly$Graph$ly$),
  ($ly$backtracking$ly$, $ly$Backtracking$ly$)
ON CONFLICT ("slug") DO NOTHING;

-- ---- busiest-moment ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (32, $ly$busiest-moment$ly$, $ly$Busiest Moment$ly$, $ly$medium$ly$, $ly$A game server keeps a log of player sessions. Each entry of `sessions` is a
pair `[login, logout]`: the player is online from time `login` up to, but not
including, time `logout`. A player who logs out at time `t` is no longer
online at `t`, so they do not overlap with someone who logs in at `t`.

Find the largest number of players that are online at the same moment, and
the earliest moment at which that many players are online. Return them as
`[peak, time]`.

## Constraints

- `1 <= sessions.length <= 10^5`
- `sessions[i].length == 2`
- `0 <= login < logout <= 10^9`

## Notes

Only integer moments matter: the number of online players changes only at
login and logout times.
$ly$, $ly${"name":"busiestMoment","params":[{"name":"sessions","type":"int[][]"}],"returns":"int[]"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1480)
