SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$busiest-moment$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$array$ly$, $ly$sorting$ly$, $ly$prefix-sum$ly$);

