-- ---- checkpoint-tour ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (49, $ly$checkpoint-tour$ly$, $ly$Checkpoint Tour$ly$, $ly$hard$ly$, $ly$An orienteering course is laid out on a city grid. `points[i] = [x, y]` is
the position of checkpoint `i`. The runner starts at checkpoint `0` and must
stamp every other checkpoint at least once, in any order; the run ends at
whichever checkpoint is stamped last (there is no need to return to the
start).

The streets form a grid, so walking from `[x1, y1]` to `[x2, y2]` takes
`|x1 - x2| + |y1 - y2|` metres. Passing over a checkpoint without stopping
does not stamp it, but that never matters: walking via a checkpoint is never
shorter than walking straight past it.

Return the length of the shortest possible run.

## Constraints

- `1 <= points.length <= 12`
- `points[i].length == 2`
- `-10^6 <= x, y <= 10^6`
- Two checkpoints may share a position.

## Notes

Trying every order of the checkpoints takes `11!` steps for the largest
input. What matters about a partial run is only which checkpoints are
stamped and where the runner stands, so store the best length for each such
pair, with the set of stamped checkpoints as a bit mask.
$ly$, $ly${"name":"shortestTour","params":[{"name":"points","type":"int[][]"}],"returns":"int"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 2080)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$checkpoint-tour$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$checkpoint-tour$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$bit-manipulation$ly$, $ly$dynamic-programming$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$checkpoint-tour$ly$);
INSERT INTO "test_cases" ("problem_id", "position", "input", "expected", "is_sample")
