-- ---- earliest-free-server ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (38, $ly$earliest-free-server$ly$, $ly$Earliest Free Server$ly$, $ly$medium$ly$, $ly$A render farm has `servers` machines numbered `0` to `servers - 1`. At time
`0` every machine is idle and a queue of render jobs is waiting; job `i` takes
`jobs[i]` time units on any machine.

The scheduler hands out the jobs one by one in queue order. Each job goes to
the machine that becomes idle the earliest (at time `0` all of them are idle);
when several machines become idle at the same time, the one with the smallest
number gets the job. A machine runs one job at a time, without pauses, and
starts its next job the moment the previous one ends.

Return an array of length `servers` whose element `k` is the time at which
machine `k` finishes its last job, or `0` if machine `k` never gets a job.

## Constraints

- `1 <= servers <= 10^4`
- `0 <= jobs.length <= 10^5`
- `1 <= jobs[i] <= 10^4`
$ly$, $ly${"name":"serverFinishTimes","params":[{"name":"servers","type":"int"},{"name":"jobs","type":"int[]"}],"returns":"int[]"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1670)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$earliest-free-server$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$earliest-free-server$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$heap$ly$, $ly$array$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$earliest-free-server$ly$);
INSERT INTO "test_cases" ("problem_id", "position", "input", "expected", "is_sample")
