-- ---- edit-distance ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (19, $ly$edit-distance$ly$, $ly$Edit Distance$ly$, $ly$hard$ly$, $ly$You want to turn the string `word1` into the string `word2` using a sequence of single-character edits. Each of the following counts as one edit:

- **Insert** one character at any position.
- **Delete** one character.
- **Replace** one character with a different one.

Return the smallest number of edits that transforms `word1` into exactly `word2`. If the two strings are already equal, the answer is `0`.

## Constraints

- `0 <= word1.length, word2.length <= 500`
- Both strings consist only of lowercase English letters.

## Notes

- Either string may be empty: turning a string into the empty string takes one deletion per character, and the reverse takes one insertion per character.
- Exploring all edit sequences is exponential; a solution of about `word1.length * word2.length` steps is expected.
$ly$, $ly${"name":"minDistance","params":[{"name":"word1","type":"string"},{"name":"word2","type":"string"}],"returns":"int"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1900)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$edit-distance$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$edit-distance$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$string$ly$, $ly$dynamic-programming$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$edit-distance$ly$);
INSERT INTO "test_cases" ("problem_id", "position", "input", "expected", "is_sample")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$edit-distance$ly$), v.* FROM (VALUES
  (0, $ly${"word1":"kitten","word2":"sitting"}$ly$::jsonb, $ly$3$ly$::jsonb, TRUE),
  (1, $ly${"word1":"sunday","word2":"saturday"}$ly$::jsonb, $ly$3$ly$::jsonb, TRUE),
  (2, $ly${"word1":"","word2":"abc"}$ly$::jsonb, $ly$3$ly$::jsonb, TRUE),
  (3, $ly${"word1":"","word2":""}$ly$::jsonb, $ly$0$ly$::jsonb, FALSE),
  (4, $ly${"word1":"a","word2":""}$ly$::jsonb, $ly$1$ly$::jsonb, FALSE),
  (5, $ly${"word1":"same","word2":"same"}$ly$::jsonb, $ly$0$ly$::jsonb, FALSE),
  (6, $ly${"word1":"abcd","word2":"wxyz"}$ly$::jsonb, $ly$4$ly$::jsonb, FALSE),
  (7, $ly${"word1":"flaw","word2":"lawn"}$ly$::jsonb, $ly$2$ly$::jsonb, FALSE),
  (8, $ly${"word1":"","word2":""}$ly$::jsonb, $ly$444$ly$::jsonb, FALSE),
  (9, $ly${"word1":"","word2":""}$ly$::jsonb, $ly$219$ly$::jsonb, FALSE),
  (10, $ly${"word1":"","word2":""}$ly$::jsonb, $ly$446$ly$::jsonb, FALSE),
  (11, $ly${"word1":"","word2":"z"}$ly$::jsonb, $ly$499$ly$::jsonb, FALSE),
  (12, $ly${"word1":"","word2":""}$ly$::jsonb, $ly$200$ly$::jsonb, FALSE),
  (13, $ly${"word1":"","word2":""}$ly$::jsonb, $ly$40$ly$::jsonb, FALSE)
