  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$first-overdraft-day$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$first-overdraft-day$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$array$ly$, $ly$prefix-sum$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$first-overdraft-day$ly$);
